const fs = require('node:fs'), crypto = require('node:crypto'), cp = require('node:child_process');
const ts = require('/home/hby/dev/AI-Werewolf-Arena/backend/node_modules/typescript');
const root = '/home/hby/dev/AI-Werewolf-Arena';
process.chdir(root);
const dir = '/tmp/awa-daytime-interruption-composition';
const before = JSON.parse(fs.readFileSync(dir+'/before.json','utf8'));
const old = cp.execFileSync('git',['show',before.base+':'+before.path],{encoding:'utf8'});
const current = fs.readFileSync(before.path,'utf8');
const sha = s => crypto.createHash('sha256').update(s).digest('hex');
if(sha(old)!==before.sha256) throw new Error('baseline_git_sha_mismatch');
const parse = text => ts.createSourceFile('same.ts',text,ts.ScriptTarget.Latest,true);
const isDoc = k => k >= ts.SyntaxKind.FirstJSDocNode && k <= ts.SyntaxKind.LastJSDocNode;
function nodes(sf) { const out=[]; function visit(n) { if(isDoc(n.kind)||n.kind===ts.SyntaxKind.EndOfFileToken) return; const children=n.getChildren(sf).filter(c=>!isDoc(c.kind)&&c.kind!==ts.SyntaxKind.EndOfFileToken); out.push([n.kind,children.length?null:n.getText(sf)]); for(const c of children) { visit(c); } } visit(sf); return out; }
function replaceOnce(s,a,b) { if(s.split(a).length!==2) throw new Error('nonunique_delta:'+a); return s.replace(a,b); }
let inverse=current;
inverse=replaceOnce(inverse,'import { createDaytimeInterruptionComposition } from "../../../rulesets/daytime-interruption-composition";\nimport type { DaytimeInterruptionComposition } from "../daytime-interruption-contracts";', 'import { hasActiveDebate } from "../../mechanisms/roles/debater/authority";\nimport { DebaterWindow } from "../../mechanisms/roles/debater/window";');
inverse=replaceOnce(inverse,'import { isSelfDestructWindowEnabled } from "../self_destruct_window";', 'import { SelfDestructWindow, isSelfDestructWindowEnabled } from "../self_destruct_window";\nimport { KnightDuelWindow } from "../knight_duel_window";');
inverse=replaceOnce(inverse,'  private readonly interruptions: DaytimeInterruptionComposition;', '  private readonly selfDestructWindow: SelfDestructWindow;\n  private readonly knightDuelWindow: KnightDuelWindow;\n  private readonly debaterWindow: DebaterWindow;');
const newConstructor='    this.interruptions = createDaytimeInterruptionComposition({\n      world: () => this.world,\n      roleRegistry: () => this.roleRegistry,\n      toolGateway: () => this.toolGateway,\n      events: () => this.events,\n    });';
const oldConstructor='    this.selfDestructWindow = new SelfDestructWindow(\n      this.world,\n      this.roleRegistry,\n      this.toolGateway,\n    );\n    this.knightDuelWindow = new KnightDuelWindow(this.world, this.toolGateway);\n    this.debaterWindow = new DebaterWindow(this.world, this.toolGateway, this.events);';
inverse=replaceOnce(inverse,newConstructor,oldConstructor);
inverse=replaceOnce(inverse,'    this.interruptions.assertEntry();','    if (hasActiveDebate(this.world)) throw new Error("debate_window_reentry");');
const routeCounts={};
for(const [now,prior] of [['this.interruptions.selfDestruct','this.selfDestructWindow'],['this.interruptions.duel','this.knightDuelWindow'],['this.interruptions.debate','this.debaterWindow']]) { routeCounts[now]=inverse.split(now).length-1; inverse=inverse.split(now).join(prior); }
if(JSON.stringify(routeCounts)!==JSON.stringify({'this.interruptions.selfDestruct':3,'this.interruptions.duel':3,'this.interruptions.debate':1})) throw new Error('route_count_mismatch');
const oldTree=nodes(parse(old)), newTree=nodes(parse(inverse));
const wholeProgram={oldNodes:oldTree.length,inverseNodes:newTree.length,identical:JSON.stringify(oldTree)===JSON.stringify(newTree),oldNodeSha256:sha(JSON.stringify(oldTree)),inverseNodeSha256:sha(JSON.stringify(newTree))};
const emissions=[];
for(const [name,module] of [['ESNext',ts.ModuleKind.ESNext],['CommonJS',ts.ModuleKind.CommonJS]]) { const compile=s=>ts.transpileModule(s,{compilerOptions:{target:ts.ScriptTarget.ES2022,module,removeComments:true}}).outputText; const a=compile(old),b=compile(inverse);emissions.push({module:name,rawIdentical:a===b,oldSha256:sha(a),inverseSha256:sha(b)}); }
// 真实的非首子节点反例：首个summary未动，只改最后day摘要自爆编号，强遍历必须发现。
const mutant=inverse.replace('        selfDestructBy: null,\n      },\n      interrupted: false,','        selfDestructBy: 999,\n      },\n      interrupted: false,');
if(mutant===inverse) throw new Error('canary_not_applied');
const canary={description:'最后return的selfDestructBy null→999，首个程序child/import未改',detected:JSON.stringify(nodes(parse(mutant)))!==JSON.stringify(oldTree)};
const composition=fs.readFileSync('backend/src/rulesets/daytime-interruption-composition.ts','utf8'), sf=parse(composition);
let movedConstructors=[];function collect(n){if(ts.isNewExpression(n)&&['SelfDestructWindow','KnightDuelWindow','DebaterWindow'].includes(n.expression.getText(sf))) movedConstructors.push(n);ts.forEachChild(n,c=>{collect(c);});} collect(sf);
const oldSf=parse(old), oldConstructors=[]; function collectOld(n) {if(ts.isNewExpression(n)&&['SelfDestructWindow','KnightDuelWindow','DebaterWindow'].includes(n.expression.getText(oldSf))) oldConstructors.push(n);ts.forEachChild(n,c=>{collectOld(c);});}collectOld(oldSf);
const constructorChecks=movedConstructors.map((n,i)=>{const mapped=n.getText(sf).replace(/runtime\.(world|roleRegistry|toolGateway|events)\(\)/g,'this.$1');const expected=oldConstructors[i]?.getText(oldSf);return {constructor:n.expression.getText(sf),wholeNodesIdentical:JSON.stringify(nodes(parse(mapped)))===JSON.stringify(nodes(parse(expected))),currentArguments:n.arguments.map(x=>x.getText(sf)),oldArguments:oldConstructors[i].arguments.map(x=>x.getText(oldSf))};});
const admission=sf.statements.find(ts.isFunctionDeclaration).body.statements.at(-1).expression.properties.find(x=>x.name.getText(sf)==='assertEntry').body.statements[0];
const admissionMapped=admission.getText(sf).replace('runtime.world()','this.world');
const oldClass=oldSf.statements.find(ts.isClassDeclaration), oldExecute=oldClass.members.find(n=>n.name?.getText(oldSf)==='execute');
const admissionSame=JSON.stringify(nodes(parse(admissionMapped)))===JSON.stringify(nodes(parse(oldExecute.body.statements[0].getText(oldSf))));
const controls=before.controls.map(x=>({...x,actualSha256:sha(fs.readFileSync(x.path)),identical:x.sha256===sha(fs.readFileSync(x.path))}));
const paths=JSON.parse(fs.readFileSync(dir+'/paths.json'));const scope=paths.map(path=>({path,sha256:sha(fs.readFileSync(path))}));
const result={base:before.base,baseline:before,scope,routeCounts,wholeProgram,emissions,constructorChecks,admissionSame,canary,controls,allowedApiDifferences:['Pipeline三反射私有字段退休，改由单interruptions聚合字段保存窄实例视图；不承诺旧反射布局／替换字段继续影响调度。','factory新增聚合对象与assertEntry方法；原execute接收者仍原窗口实例，非bind/clone。','原具体Debater直导退出；新的factory静态加载各窗口顺序不同，不宣称模块初始化图完全相同。'],limitations:['逆向证明仅覆盖明确字段／装配／准入／7调用点迁移，不能证明新增组合任意外部使用均旧API兼容。','没有宣称迁移全部白天机制、状态、付款或死亡／终局owner。'],approved:wholeProgram.identical&&emissions.every(x=>x.rawIdentical)&&constructorChecks.length===3&&constructorChecks.every(x=>x.wholeNodesIdentical)&&admissionSame&&canary.detected&&controls.every(x=>x.identical)};
fs.writeFileSync('docs/refactor/generated/daytime-interruption-program-proof.json',JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify({approved:result.approved,wholeProgram,constructorChecks,emissions,admissionSame,canary,controlsMatch:controls.every(x=>x.identical)}));
